def verify():
    assert abs(math.cos(0) + math.cos(math.pi / 2) - 1) < 1e-12 and abs(math.sin(0) + math.sin(math.pi / 2) - 1) < 1e-12
    assert abs(2 * 9.81 * 0.5 - 9.81) < 1e-12 and 0.5 * 100 * 0.8 == 40 and 3000 / 100 == 30 and abs(360 / 4096 - 0.0879) < 0.0001
    assert abs(10 * 0.05 - 0.5) < 1e-12 and abs(2 * math.pi * 0.1 * 10 - 6.283) < 0.001 and abs(0.5 * 0.4 - 0.2) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
